import { Dimensions, StyleSheet } from 'react-native';

const { width } = Dimensions.get('window');

export const styles = StyleSheet.create({
    modalContainer: {
    flex: 1,
    backgroundColor: '#fff'
  },
  modalHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    borderBottomWidth: 1,
    borderBottomColor: '#eee'
  },
  cancelText: {
    fontSize: 16,
    color: '#007AFF'
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: '500'
  },
  footerInfo: {
    padding: 16,
    alignItems: 'center'
  },
  footerText: {
    fontSize: 14,
    color: '#666'
  }
});
